          "tests": "for _ in range(30):\n    p = generate_password(12)\n    assert len(p) == 12, \"Длина должна быть 12\"\n    assert any(c.islower() for c in p), \"Нужна строчная буква\"\n    assert any(c.isupper() for c in p), \"Нужна заглавная буква\"\n    assert any(c.isdigit() for c in p), \"Нужна цифра\"\n    assert any(not c.isalnum() for c in p), \"Нужен символ\"\nq = generate_password(20, use_symbols=False)\nassert len(q) == 20 and q.isalnum(), \"Без символов: только буквы и цифры\"\nassert generate_password(16) != generate_password(16), \"Два пароля подряд не должны совпадать\"\ntry:\n    generate_password(5)\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError(\"Короче 8 символов — ValueError\")\ns, tips = check_password(\"Zx9!kLm2pQw7\")\nassert s == 5 and tips == [], \"Хороший пароль: 5 баллов, советов нет\"\ns, tips = check_password(\"abc\")\nassert s == 1 and len(tips) == 4, \"'abc' — только строчные: 1 балл, 4 совета\"\ns, tips = check_password(\"qwerty\")\nassert s == 0, \"Популярный пароль — 0 баллов\"\nassert any(\"популяр\" in t for t in tips), \"Нужен совет про популярный пароль\"\ns, _ = check_password(\"Password12345\")\nassert s == 4, \"Длинный, заглавные, строчные, цифры — но без символа: 4\"\nprint(\"ok\")",
          "solution": "import secrets\nimport string\n\n\ndef generate_password(length=16, use_symbols=True):\n    \"\"\"Случайный пароль: гарантированно есть строчная, заглавная, цифра (и символ).\"\"\"\n    if length < 8:\n        raise ValueError(\"Пароль короче 8 символов небезопасен\")\n    pools = [string.ascii_lowercase, string.ascii_uppercase, string.digits]\n    if use_symbols:\n        pools.append(\"!@#$%^&*-_?\")\n    chars = [secrets.choice(p) for p in pools]  # по одному символу из каждой группы\n    alphabet = \"\".join(pools)\n    while len(chars) < length:\n        chars.append(secrets.choice(alphabet))\n    # перемешиваем безопасным генератором\n    result = []\n    while chars:\n        result.append(chars.pop(secrets.randbelow(len(chars))))\n    return \"\".join(result)\n\n\ndef check_password(pw):\n    \"\"\"Вернуть (оценка 0..5, список советов).\"\"\"\n    score = 0\n    tips = []\n    if len(pw) >= 12:\n        score += 1\n    else:\n        tips.append(\"Сделай пароль длиннее 12 символов\")\n    if any(c.islower() for c in pw):\n        score += 1\n    else:\n        tips.append(\"Добавь строчные буквы\")\n    if any(c.isupper() for c in pw):\n        score += 1\n    else:\n        tips.append(\"Добавь заглавные буквы\")\n    if any(c.isdigit() for c in pw):\n        score += 1\n    else:\n        tips.append(\"Добавь цифры\")\n    if any(not c.isalnum() for c in pw):\n        score += 1\n    else:\n        tips.append(\"Добавь символы вроде !@#\")\n    if pw.lower() in (\"password\", \"qwerty\", \"123456\", \"12345678\", \"letmein\", \"admin\"):\n        score = 0\n        tips.append(\"Это один из самых популярных паролей мира\")\n    return score, tips\n",
