          "tests": "assert encode_text(\"flag{test}\", \"base64\") == \"ZmxhZ3t0ZXN0fQ==\", \"base64('flag{test}')\"\nassert decode_text(\"ZmxhZ3t0ZXN0fQ==\", \"base64\") == \"flag{test}\", \"обратно из base64\"\nassert encode_text(\"abc\", \"hex\") == \"616263\", \"hex('abc')\"\nassert decode_text(\"616263\", \"hex\") == \"abc\", \"обратно из hex\"\nassert encode_text(\"a b/c\", \"url\") == \"a%20b%2Fc\", \"url: пробел и слэш кодируются\"\nassert decode_text(\"a%20b%2Fc\", \"url\") == \"a b/c\", \"обратно из url\"\nfor m in (\"base64\", \"hex\", \"url\"):\n    assert decode_text(encode_text(\"привет, мир!\", m), m) == \"привет, мир!\", \"Кириллица должна проходить туда-обратно: \" + m\ntry:\n    encode_text(\"x\", \"rot47\")\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError(\"Неизвестный метод: ValueError\")\nprint(\"ok\")",
